"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useEffect, useId, useState } from "react";

import { CheckIcon, ChevronDownIcon, CircleCheckIcon, RefreshIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { DIFF, PLAN_STEPS, STEPS, TASK } from "./agent-run/data";
import { DiffReview } from "./agent-run/diff-review";
import { RunState, type RunPhase } from "./agent-run/run-state";
import { StepRow } from "./agent-run/step-row";
import { BranchIcon, MergeIcon } from "./icons";
import { formatSeconds } from "./lib/format";
import { useElapsed } from "./lib/timers";
import { Reveal } from "./parts/reveal";

// Critically damped: 2 * sqrt(420) is about 41.
const GROW = { type: "spring", stiffness: 420, damping: 41, mass: 1 } as const;

const ADDED = DIFF.reduce((total, file) => total + file.added, 0);
const REMOVED = DIFF.reduce((total, file) => total + file.removed, 0);

/**
 * One card that follows a coding agent through a task. Steps stream in, the
 * live verb shimmers, and each finished step opens to its input and output.
 * The agent stops on its change for a person to approve, then writes, tests
 * and folds its steps into one line beside the result.
 */
export function AgentRun({ className }: { className?: string }) {
  const titleId = useId();
  const stepsId = useId();
  const reduceMotion = useReducedMotion();
  const [runKey, setRunKey] = useState(0);
  const [phase, setPhase] = useState<RunPhase>("working");
  const [done, setDone] = useState(0);
  const [openId, setOpenId] = useState<string | null>(null);
  const [folded, setFolded] = useState(true);
  const [pullRequest, setPullRequest] = useState(false);

  const active = phase === "working" || phase === "writing";
  const current = active ? STEPS[done] : undefined;
  const elapsed = useElapsed(active, runKey);

  useEffect(() => {
    if (!current) return;
    const id = window.setTimeout(() => {
      const next = done + 1;
      setDone(next);
      if (phase === "working" && next >= PLAN_STEPS) setPhase("review");
      else if (next >= STEPS.length) setPhase("done");
    }, current.duration);
    return () => window.clearTimeout(id);
  }, [current, done, phase]);

  const restart = () => {
    setRunKey((key) => key + 1);
    setPhase("working");
    setDone(0);
    setOpenId(null);
    setFolded(true);
    setPullRequest(false);
  };

  const visible = STEPS.slice(0, current ? done + 1 : done);
  const showSteps = phase !== "done" || !folded;

  return (
    <BlockFrame aria-labelledby={titleId} className={cn("mx-auto max-w-2xl", className)}>
      <header className="flex items-start justify-between gap-3 border-b border-border px-5 py-4">
        <div className="flex min-w-0 flex-col gap-1.5">
          <h2 id={titleId} className="text-base font-semibold text-balance">
            {TASK.title}
          </h2>
          <p className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
            <span className="inline-flex items-center gap-1">
              <BranchIcon aria-hidden="true" className="size-3.5" />
              <span className="font-mono">{TASK.repo}</span>
            </span>
            <span>{TASK.model}</span>
            <RunState phase={phase} />
            <span className="tabular-nums">{formatSeconds(elapsed)}</span>
          </p>
        </div>
        <Button variant="ghost" size="icon" aria-label="Restart the run" onClick={restart}>
          <RefreshIcon aria-hidden="true" className="size-4" />
        </Button>
      </header>

      <div className="flex flex-col gap-3 p-3">
        {phase === "done" ? (
          <Button
            variant="ghost"
            aria-expanded={!folded}
            aria-controls={stepsId}
            onClick={() => setFolded(!folded)}
            size="sm"
            className="w-full justify-start"
          >
<span className="flex min-h-10 w-full items-center gap-3 px-2 py-2 font-normal">
            <CircleCheckIcon aria-hidden="true" className="size-4 text-marketing-green-ink" />
            <span className="flex-1 text-left text-sm">
              Ran {STEPS.length} steps in {formatSeconds(elapsed)}
            </span>
            <ChevronDownIcon
              aria-hidden="true"
              className={cn("size-4 text-muted-foreground motion-safe:transition-transform", !folded && "rotate-180")}
            />
          </span>
</Button>
        ) : null}

        <Reveal open={showSteps} id={stepsId}>
          <ol aria-label="Steps" className="flex flex-col">
            <AnimatePresence initial={false}>
              {visible.map((step, index) => (
                <motion.li
                  key={`${runKey}-${step.id}`}
                  initial={reduceMotion ? false : { height: 0, opacity: 0 }}
                  animate={{ height: "auto", opacity: 1 }}
                  transition={reduceMotion ? { duration: 0 } : { height: GROW, opacity: { duration: 0.2, delay: 0.05 } }}
                  className="overflow-hidden"
                >
                  <StepRow
                    step={step}
                    live={active && index === done}
                    open={openId === step.id}
                    onToggle={() => setOpenId(openId === step.id ? null : step.id)}
                  />
                </motion.li>
              ))}
            </AnimatePresence>
          </ol>
        </Reveal>

        {phase === "review" ? (
          <DiffReview files={DIFF} onApprove={() => setPhase("writing")} onReject={() => setPhase("rejected")} />
        ) : null}

        {phase === "rejected" ? (
          <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border px-4 py-3">
            <p className="text-sm text-muted-foreground">Change rejected. Nothing was written.</p>
            <Button variant="outline" size="sm" onClick={restart}>
              <RefreshIcon aria-hidden="true" className="size-4" />
              Start again
            </Button>
          </div>
        ) : null}

        {phase === "done" ? (
          <section aria-label="Result" className="flex flex-col gap-4 rounded-xl border border-border p-4">
            <dl className="grid grid-cols-3 gap-3">
              <div className="flex flex-col gap-0.5">
                <dt className="text-xs text-muted-foreground">Files changed</dt>
                <dd className="text-lg font-semibold tabular-nums">{DIFF.length}</dd>
              </div>
              <div className="flex flex-col gap-0.5">
                <dt className="text-xs text-muted-foreground">Lines</dt>
                <dd className="text-lg font-semibold tabular-nums">
                  <span className="text-marketing-green-ink">+{ADDED}</span>{" "}
                  <span className="text-marketing-orange-ink">-{REMOVED}</span>
                </dd>
              </div>
              <div className="flex flex-col gap-0.5">
                <dt className="text-xs text-muted-foreground">Checks</dt>
                <dd className="flex items-center gap-1 text-lg font-semibold tabular-nums">
                  <CheckIcon aria-hidden="true" className="size-4 text-marketing-green-ink" />
                  18 of 18
                </dd>
              </div>
            </dl>
            <div className="flex flex-wrap items-center justify-between gap-3">
              <p role="status" className="text-sm text-muted-foreground">
                {pullRequest ? "Pull request 482 is open for review." : "Ready on branch waitlist-full-days."}
              </p>
              <Button size="sm" disabled={pullRequest} onClick={() => setPullRequest(true)}>
                <MergeIcon aria-hidden="true" className="size-4" />
                {pullRequest ? "Pull request opened" : "Open pull request"}
              </Button>
            </div>
          </section>
        ) : null}
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

