import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

/** The kind of work a step does. It picks the step's icon. */
export type StepKind = "plan" | "read" | "search" | "edit" | "run";

/** One step of the agent's run. */
export interface RunStep {
  id: string;
  kind: StepKind;
  /** The verb while the step runs, such as "Reading". */
  live: string;
  /** The verb once it ends, such as "Read". */
  past: string;
  /** What the step works on, such as a file path. Shown as code. */
  target: string;
  /** How long the step takes, in milliseconds of the simulation. */
  duration: number;
  input: string;
  output: string;
}

/** One line of a file diff. */
export interface DiffLine {
  kind: "add" | "del" | "same";
  /** The line number in the new file, or in the old file for a removed line. */
  line: number;
  text: string;
}

/** One file the agent wants to change. */
export interface DiffFile {
  path: string;
  added: number;
  removed: number;
  lines: DiffLine[];
}

/** The task the agent works on. */
export const TASK = {
  title: "Offer a waitlist when a clinic day is full",
  repo: "fernhill/booking-web",
  model: "Larch 2",
};

/** The steps before the agent asks to write. The rest run after approval. */
export const PLAN_STEPS = 5;

/** Every step of the run, in order. */
export const STEPS: RunStep[] = [
  {
    id: "plan",
    kind: "plan",
