"use client";

import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";

import type { DiffFile, DiffLine } from "./data";

/** Props for the change the agent asks to write. */
export interface DiffReviewProps {
  files: DiffFile[];
  onApprove: () => void;
  onReject: () => void;
}

const LINE_TEXT = {
  add: "text-marketing-green-ink",
  del: "text-marketing-orange-ink",
  same: "text-muted-foreground",
} satisfies Record<DiffLine["kind"], string>;

const LINE_SURFACE = {
  add: "bg-marketing-green-surface",
  del: "bg-marketing-orange-surface",
  same: "",
} satisfies Record<DiffLine["kind"], string>;

const LINE_SIGN = { add: "+", del: "-", same: " " } satisfies Record<DiffLine["kind"], string>;
const LINE_WORD = { add: "Added", del: "Removed", same: "" } satisfies Record<DiffLine["kind"], string>;

/**
 * The agent's proposed change: one tab per file with its added and removed
 * lines, then Reject and Approve. Nothing is written until a person approves.
 */
export function DiffReview({ files, onApprove, onReject }: DiffReviewProps) {
  const first = files[0];
  if (!first) return null;
  return (
    <section aria-label="Change waiting for approval" className="flex flex-col gap-3 rounded-xl border border-border p-3">
      <p className="text-sm">
        <span className="font-medium">Larch wants to write 2 files.</span>{" "}
        <span className="text-muted-foreground">Review the change before it is saved.</span>
      </p>
      <Tabs defaultValue={first.path} className="min-w-0">
        <div className="max-w-full overflow-x-auto scroll-fade-effect-x scrollbar-none">
          <TabsList>
            {files.map((file) => (
              <TabsTrigger key={file.path} value={file.path}>
                <span className="flex items-center gap-1.5 font-mono text-xs">
                  {file.path.split("/").pop()}
                  <span className="text-marketing-green-ink">+{file.added}</span>
                  <span className="text-marketing-orange-ink">-{file.removed}</span>
                </span>
              </TabsTrigger>
            ))}
          </TabsList>
        </div>
        {files.map((file) => (
          <TabsContent key={file.path} value={file.path} className="min-w-0">
            <div className="overflow-x-auto scroll-fade-effect-x scrollbar-none rounded-lg bg-muted">
              <p className="border-b border-border px-3 py-1.5 font-mono text-xs text-muted-foreground">{file.path}</p>
              <ol className="py-1 font-mono text-xs">
                {file.lines.map((line, index) => (
                  <li key={index} className="relative flex min-w-max">
                    <span aria-hidden="true" className={cn("absolute inset-0", LINE_SURFACE[line.kind])} />
                    <span aria-hidden="true" className="relative w-10 shrink-0 pr-2 text-right text-muted-foreground tabular-nums">
                      {line.line}
                    </span>
                    <span aria-hidden="true" className={cn("relative w-4 shrink-0", LINE_TEXT[line.kind])}>
                      {LINE_SIGN[line.kind]}
                    </span>
                    {LINE_WORD[line.kind] ? <span className="sr-only">{LINE_WORD[line.kind]}: </span> : null}
                    <span className={cn("relative pr-3 whitespace-pre", line.kind === "same" ? "text-muted-foreground" : "text-foreground")}>
                      {line.text || " "}
                    </span>
                  </li>
                ))}
              </ol>
            </div>
          </TabsContent>
        ))}
      </Tabs>
      <div className="flex flex-wrap justify-end gap-2">
        <Button variant="outline" size="sm" onClick={onReject}>
          Reject
        </Button>
        <Button size="sm" onClick={onApprove}>
          Approve and write
        </Button>
      </div>
    </section>
  );
}

import { cn } from "@/lib/utils";

/** Where the run is: working, waiting for a person, writing after approval, finished, or stopped. */
export type RunPhase = "working" | "review" | "writing" | "done" | "rejected";

const WORD = {
  working: "Working",
  review: "Waiting for you",
  writing: "Writing",
  done: "Done",
  rejected: "Stopped",
} satisfies Record<RunPhase, string>;

const DOT = {
  working: "bg-chart-1 motion-safe:animate-pulse",
  review: "bg-marketing-amber-ink",
  writing: "bg-chart-1 motion-safe:animate-pulse",
  done: "bg-marketing-green-ink",
  rejected: "bg-muted-foreground",
} satisfies Record<RunPhase, string>;

/** A dot and a word for the run's state. The word is a live region, so a change is read out. */
export function RunState({ phase }: { phase: RunPhase }) {
  return (
    <span role="status" className="inline-flex items-center gap-1.5 text-foreground">
      <span aria-hidden="true" className={cn("size-1.5 rounded-full", DOT[phase])} />
      {WORD[phase]}
    </span>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, type SVGProps, type ReactNode } from "react";

import { CheckIcon, ChevronDownIcon, SparklesIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { FileIcon, PencilIcon, SearchIcon, TerminalIcon } from "../icons";
import { ShimmerText } from "../parts/shimmer-text";
import { Reveal } from "../parts/reveal";
import type { RunStep, StepKind } from "./data";
import { IoBlock } from "./io-block";

const KIND_ICON = {
  plan: SparklesIcon,
  read: FileIcon,
  search: SearchIcon,
  edit: PencilIcon,
  run: TerminalIcon,
} satisfies Record<StepKind, (props: SVGProps<SVGSVGElement>) => ReactNode>;

/** Props for one step of a run. */
export interface StepRowProps {
  step: RunStep;
  /** True while the agent works on this step. */
  live: boolean;
  open: boolean;
  onToggle: () => void;
}

/**
 * One step: its icon, its verb and target, how long it took and a check.
 * The live verb shimmers and crossfades to the past tense when the step ends.
 * A finished step opens in place to show what went in and what came out.
 */
export function StepRow({ step, live, open, onToggle }: StepRowProps) {
  const reduceMotion = useReducedMotion();
  const panelId = useId();
  const Icon = KIND_ICON[step.kind];
  const verb = live ? step.live : step.past;

  return (
    <div className="flex flex-col">
      <Button
        variant="ghost"
        aria-expanded={live ? undefined : open}
        aria-controls={live ? undefined : panelId}
        aria-disabled={live || undefined}
        onClick={live ? undefined : onToggle}
        size="sm"
        className="w-full justify-start"
      >
<span className="flex min-h-10 w-full items-center gap-3 px-2 py-2 text-left font-normal">
        <Icon aria-hidden="true" className="size-4 text-muted-foreground" />
        <span className="flex min-w-0 flex-1 items-baseline gap-1.5 text-sm">
          <span className="relative inline-grid shrink-0">
            <AnimatePresence initial={false} mode="popLayout">
              <motion.span
                key={verb}
                initial={reduceMotion ? false : { opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                transition={{ duration: reduceMotion ? 0 : 0.2 }}
                className="col-start-1 row-start-1 font-medium"
              >
                <ShimmerText text={verb} active={live} />
              </motion.span>
            </AnimatePresence>
          </span>
          <code className="truncate font-mono text-xs text-muted-foreground">{step.target}</code>
        </span>
        {live ? (
          <span className="text-xs text-muted-foreground">Working</span>
        ) : (
          <>
            <span className="text-xs tabular-nums text-muted-foreground">{(step.duration / 1000).toFixed(1)}s</span>
            <CheckIcon aria-hidden="true" className="size-4 text-marketing-green-ink" />
            <ChevronDownIcon
              aria-hidden="true"
              className={cn("size-4 text-muted-foreground motion-safe:transition-transform", open && "rotate-180")}
            />
          </>
        )}
      </span>
</Button>
      <Reveal open={open && !live} id={panelId} className="grid gap-2 pt-1 pb-3 pl-9 pr-2">
        <IoBlock label="Input" text={step.input} />
        <IoBlock label="Output" text={step.output} />
      </Reveal>
    </div>
  );
}

